33	fn does_dtype_have_sufficient_order(dtype: &DataType) -> bool {
34	    // Rules surrounding floats are really complicated. I should get around to that.
35	    !dtype.is_nested() && !dtype.is_float() && !dtype.is_null() && !dtype.is_categorical()
36	}
37	
38	fn is_stat_defined(
39	    expr: impl IntoAExprBuilder,
40	    dtype: &DataType,
41	    arena: &mut Arena<AExpr>,
42	) -> AExprBuilder {
43	    let mut expr = expr.into_aexpr_builder();
44	    expr = expr.is_not_null(arena);
45	    if dtype.is_float() {
46	        let is_not_nan = expr.is_not_nan(arena);
47	        expr = expr.and(is_not_nan, arena);
48	    }
49	    expr
50	}
