+/// Whether a literal is a statically-known floating point NaN value.
+///
+/// Parquet min/max statistics exclude NaN values, so comparisons involving NaN require special
+/// handling to avoid incorrectly skipping batches that contain hidden NaN values.
+fn literal_is_nan(lv: &LiteralValue) -> bool {
